function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 3 || nums.length > 10000) return 'nums needs 3 to 10,000 lengths.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each length is an integer from 1 to 10^6.';
  return null;
}

