function largestPerimeter(nums) {
  nums.sort((a, b) => b - a);
  for (let i = 0; i + 2 < nums.length; i++) {
    const longest = nums[i];
    const others = nums[i + 1] + nums[i + 2];
    if (longest < others) {
      return longest + others;
    }
  }
  return 0;
}

