function largestPerimeter(nums) {
  let best = 0;
  const n = nums.length;
  for (let a = 0; a < n; a++)
    for (let b = a + 1; b < n; b++)
      for (let c = b + 1; c < n; c++) {
        const x = nums[a], y = nums[b], z = nums[c];
        if (x + y > z && x + z > y && y + z > x) best = Math.max(best, x + y + z);
      }
  return best;
}

