function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    // A few fast-growing lengths at the top cannot form triangles, so the scan must walk past them.
    const nums = [];
    let a = pick(1, 50), b = a + pick(0, 50);
    while (a + b <= 1000000 && nums.length < 30) { nums.push(a); [a, b] = [b, a + b]; }
    while (nums.length < 2000) nums.push(pick(1, rand() < 0.5 ? 1000 : 1000000));
    for (let i = nums.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [nums[i], nums[j]] = [nums[j], nums[i]]; }
    return [nums];
  }
  const n = pick(3, 9), shape = rand();
  if (shape < 0.3) {
    // Fibonacci-like lengths: every three sorted neighbours are degenerate or impossible.
    const nums = [];
    let a = pick(1, 3), b = a + pick(0, 3);
    for (let i = 0; i < n; i++) { nums.push(a); [a, b] = [b, a + b]; }
    if (rand() < 0.5) nums[pick(0, n - 1)] = pick(1, 40);
    return [nums.sort(() => rand() - 0.5)];
  }
  const high = shape < 0.6 ? 6 : shape < 0.9 ? 100 : 1000000;
  return [Array.from({ length: n }, () => pick(1, high))];
}
